  "claim": {
    "component_id": "C034.component",
    "value": "Calling a reduction locally minimal requires exhaustive single-component removal checks.",
    "scope": "Necessary checking requirement for the local-minimality label; performing checks alone is not stated to guarantee the label.",
    "provenance": {
      "refs": [
        {"source_id": "P022", "role": "SUPPORT"},
        {"source_id": "P021", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P022 explicitly supplies the necessary checking requirement; P021 identifies the test-relative reduction under discussion."
    }
  },
  "signal_basis": {
    "component_id": "C034.signal_basis",
    "value": "A reduced configuration repeatedly reproduces lateness while specified further removals cease to reproduce it, with test conditions held fixed and a common repetition rule distinguishing resolved from unresolved outcomes.",
    "scope": "The selected case under the replay test; specified removal results do not establish that every single-component removal was checked.",
    "provenance": {
      "refs": [
        {"source_id": "P018", "role": "SUPPORT"},
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P006", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the observed reduction pattern, fixed test conditions, repetition and unresolved-outcome rules, and selected-case scope."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C034.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a necessary checking requirement; no unresolved empirical bridge is required."
    }
  },
  "rationale": "Local minimality requires ruling out each remaining single-component removal as preserving failure under the test. Results for only specified removals leave unchecked possibilities. This licenses the claim's necessary checking requirement without asserting that conducting checks alone establishes local minimality.",
  "uncertainty": "The signal does not establish whether exhaustive checks occurred or yielded resolved outcomes. That limits assigning the label to a particular reduction, but does not undermine this necessary-requirement claim.",
  "anomalies": []
}
